 rel=read(p/'code-only-relations.json');limitations.append({'repo':s['repo'],'scope':s['analysisScope'],'sourceUnresolvedImportRequests':dict(collections.Counter(x['request'] for x in rel['source-improved']['unresolvedImports'])),'bundleUnresolvedImportRequests':dict(collections.Counter(x['request'] for x in rel['bundle-improved']['unresolvedImports'])),'remainingPerChunkGates':dict(collections.Counter(x['gate'] for x in local['improved-per-chunk'] if not x['recovered'])),'remainingCrossChunkGates':dict(collections.Counter(x['gate'] for x in global_['improved-cross-chunk'] if not x['recovered']))})
